def main(argv):
    common, check, part, page = False, False, 1, PAGE_BYTES
    root, facts_path, index_path = TREE, None, None
    queries = []
    it = iter(argv)
    try:
        for a in it:
            if a in ('-h', '--help'):
                sys.stdout.write(USAGE)
                return 0
            elif a == '--common':
                common = True
            elif a == '--check':
                check = True
            elif a == '--part':
                part = int(next(it))
            elif a == '--page-bytes':
                page = int(next(it))
            elif a == '--root':
                root = next(it)
            elif a == '--facts':
                facts_path = next(it)
            elif a == '--index':
                index_path = next(it)
            elif a.startswith('--'):
                raise ValueError('unknown option ' + a)
            else:
                queries.append(a)
    except (StopIteration, ValueError) as e:
        sys.stderr.write('facts-extract: %s\n%s' % (e or 'an option lacks its value', USAGE))
        return 2
    if not queries and not common:
        sys.stderr.write(USAGE)
